function OrganizationStudents({notice}){const [org,setOrg]=useState(null),[members,setMembers]=useState([]),[busy,setBusy]=useState(false);async function load(){try{const [o,m]=await Promise.all([api("/organization"),api("/organization/members")]);setOrg(o.organization);setMembers(m.members||[]);}catch(e){notice(e.message);}}useEffect(()=>{load();},[]);async function decide(id,status){setBusy(true);try{await api("/organization/members/"+id,{method:"PATCH",body:JSON.stringify({status})});notice("Membership updated.");await load();}catch(e){notice(e.message);}finally{setBusy(false);}}return <><section className="panel"><h3>Organization registration</h3>{org?<><p><b>{org.name}</b> · {org.status}</p><p>Share this registration code with students:</p><div className="invite-code">{org.registrationCode}<button onClick={()=>{navigator.clipboard.writeText(org.registrationCode);notice("Registration code copied.");}}>Copy code</button></div>{org.status!=="APPROVED"&&<p>Your organization is awaiting System Admin approval.</p>}</>:<p>Organization profile is being prepared.</p>}</section><section className="panel"><h3>Students and employees</h3><p>Approve or reject requests to join your organization.</p>{members.length?members.map(m=><div className="rowitem" key={m.id}><div><b>{m.user?.fullName||m.userId}</b><small>{m.user?.email} · {m.studentNumber||"No student number"} · {m.status}</small></div><div className="actions">{m.status==="PENDING"&&<><button disabled={busy||org?.status!=="APPROVED"} onClick={()=>decide(m.id,"ACTIVE")}>Approve</button><button disabled={busy} onClick={()=>decide(m.id,"REJECTED")}>Reject</button></>}</div></div>):<p className="muted">No student requests yet.</p>}</section></>}
